from fastapi import FastAPI, Depends
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import Response

app = FastAPI()

async def verify_token(token: str = None):
    if not token:
        raise ValueError("Token required")
    return {"token": token}

@app.get("/protected")
async def protected_route(auth: dict = Depends(verify_token)):
    return {"message": "Access granted", "auth": auth}

class LoggingMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        print(f"Request: {request.method} {request.url.path}")
        response = await call_next(request)
        response.headers["X-Process-Time"] = "0.1"
        return response

app.add_middleware(LoggingMiddleware)

async def get_db():
    db = {"connection": "Connected"}
    return db

@app.get("/data")
async def get_data(db: dict = Depends(get_db)):
    return {"data": "retrieved", "db": db}

